{"explanation":"Area is base times height divided by 2. Scaling by k multiplies the base by k and the height by k, so the area becomes (kb)(kh)/2 = k²·(bh/2). Another way to see it is to tile the scaled triangle with k² copies of the original. Drag the triangle's vertices and move the slider to see that the area ratio always equals k².","manimCode":"const O = [-4.5, -2.5, 0];
let k = 1;
const base = [[0,0],[2,0],[0.7,1.5]];

const orig = new Polygon({ vertices: base.map(p => [O[0]+p[0], O[1]+p[1], 0]), color: BLUE });
orig.setFill(BLUE, 0.4);

const scaled = new Polygon({ vertices: base.map(p => [O[0]+p[0]*k, O[1]+p[1]*k, 0]), color: YELLOW });
scaled.setFill(YELLOW, 0.25);

scene.add(scaled, orig);

const title = new Text({ text: 'Scale by k  →  area scales by k²', color: WHITE, fontSize: 32 });
title.moveTo([0, 3.4, 0]);
scene.add(title);

let info = null;
function area(pts) {
  const [a,b,c] = pts;
  return Math.abs((b[0]-a[0])*(c[1]-a[1]-0) - (c[0]-a[0])*(b[1]-a[1])) / 2;
}
function refresh() {
  scaled.setVertices(base.map(p => [O[0]+p[0]*k, O[1]+p[1]*k, 0]));
  if (info) scene.remove(info);
  const a0 = area(base);
  const a1 = a0 * k * k;
  info = new Text({
    text: 'k = ' + k.toFixed(1) + '   area: ' + a0.toFixed(2) + ' → ' + a1.toFixed(2) + '   ratio = ' + (a1/a0).toFixed(2) + ' = k² = ' + (k*k).toFixed(2),
    color: GREEN, fontSize: 24
  });
  info.moveTo([0, -3.4, 0]);
  scene.add(info);
}
refresh();

const controls = new Controls(scene, { position: 'top-right' });
controls.addSlider({ label: 'k', min: 0.5, max: 3, value: 1, step: 0.1, onChange: (v) => { k = v; refresh(); } });

await scene.wait(999999);"}

